We assume that we are given a finite set of samples $\{r_i\}_{i=1}^n$ drawn independently from 
\begin{equation} \mathcal{M}_\sigma \stackrel{\bigtriangleup}{=} \{q\in \mathbb{R}^D ~|~ dist(q, \mathcal{M}) < \sigma \}
,\end{equation}
a tubular neighborhood of $\mathcal{M}$.
Explicitly, we assume that $r_i \sim \operatorname{Unif}(\mathcal{M}_\sigma)$, which is the uniform distribution on $\mathcal{M}_\sigma$; i.e., the normalized Lebesgue measure with respect to $\mathbb{R}^D$.

Finally, let $p\in\mathcal{M}$, we wish to describe $W_p \subset \mathcal{M}$ a neighborhood of $p$ as a graph of a function 
\begin{equation}
\varphi_p:W_{T_p\mathcal{M}}\to \mathcal{M} \end{equation}
where $W_{T_p\mathcal{M}} = P_{T_p\mathcal{M}}(W_p)$, the projection of $W_p$ onto the tangent, and $\varphi_p$ is defined by
\begin{equation}
    \varphi_p(x) = p+(x,\phi_p(x))_{T_p\mathcal{M}} ,\end{equation}
where $x\in \mathbb{R}^d \simeq T_p\mathcal{M}$, $\phi_p(x)\in \mathbb{R}^{D-d} \simeq T_p\mathcal{M}^\perp $, and $(x,y)_{T_p\mathcal{M}} \in \mathbb{R}^D$ denotes that $x\in\mathbb{R}^d$ and $y\in\mathbb{R}^{D-d}$ represent a point in some basis of $T_p\mathcal{M}$ and $T_p\mathcal{M}^\perp$ correspondingly.

Then, we define the graph of $\phi_p$ to be
\begin{equation} \Gamma_{\phi_p, W_p} \stackrel{\bigtriangleup}{=} \{p + (x, \phi_p(x))_{T_p\mathcal{M}} | x\in W_{T_p\mathcal{M}} \}  
.\end{equation}
For simplicity, throughout the paper we identify the graph of $\phi_p$ with $\Gamma_{\phi_p,W_p}$. That is, we refer to $\mathcal{M}$ as locally a graph of $\phi_p$ (see Figure \ref{fig:SkewedH}).

Given a point $r\in\mathcal{M}_\sigma$ we limit the the region of interest (ROI) to:
\begin{equation} U_{\textrm{ROI}} = {\{r_i|\operatorname{dist}(r_i,r)<\sqrt{\sigma\tau}\}}
,\end{equation}
and denote the number of samples in the ROI by $N$.

Then, we define the relevant coordinate system as the pair $(q, H)\in \mathbb{R}^D\times Gr(d, D)$, which minimizes the functional:
\begin{equation} J_1(r; q, H) = \frac{1}{N}\sum_{r_i\in U_{\textrm{ROI}}} \operatorname{dist}^2 (r_i - q,H)
\end{equation}
under the constraints
\begin{enumerate}
    \item Orthogonality: $ r - q\perp H $.
    \item Region of interest: $ r_i \in U_{\textrm{ROI}} $.
    \item Search region: $\norm{r-q} < 2\sigma$.
\end{enumerate}

Explicitly, we denote
\begin{equation} q^*(r), H^*(r) = \arg\!\min_{\substack{ q, H \\ r-q \perp H \\ \|r- q\|<2\sigma}} J_1(r; q, H)
\end{equation}

Given $(q, H)\in \mathbb{R}^D\times Gr(d,D)$ we define the following minimization scheme, known as local polynomial regression (e.g., \cite{cleveland1979robust,mclain1976two}):
Find $\pi\in \Pi_{k-1}^{d\mapsto D}$ a polynomial of total degree $deg(\pi)\leq k-1$ from $\mathbb{R}^d$ to $\mathbb{R}^{D-d}$ which minimizes
\begin{equation} J_2(\pi ~|~ q, H) = \frac{1}{N_{q, H}}\sum_{r_i \in U_{\textrm{ROI}}^n} \norm{r_i - (x_i, \pi(x_i))_H}^2
,\end{equation}
where $x_i\in \mathbb{R}^d$ are the projections of $r_i - q$ onto $H$, $(x, y)_H\in \mathbb{R}^d\times\mathbb{R}^{D-d}$ are coefficients in a basis of $H\times H^\perp$, $U_{\textrm{ROI}}^n(q,H)$ is defined through a bandwidth $\epsilon_n$ as
\begin{equation} U_{\textrm{ROI}}^n(q,H) = {\{r_i\in U_\textrm{ROI}~|~\norm{x_i}<\epsilon_n\}}
,\end{equation}
and $N_{q, H}$ denotes the number of samples in $U_{\textrm{ROI}}^n(q, H)$.

Explicitly, the local polynomial regression is defined through
\begin{equation} \pi^*_{q, H} = \arg\!\min_{\pi\in \Pi_{k-1}^{d\mapsto D}} J_2(\pi ~|~ q, H)
.\end{equation}

As required to ensure convergence in probability for local polynomial regression \cite{aizenbud2021VectorEstimation,stone1980optimal}, we demand that the bandwidth $\epsilon_n\to 0$ as $n\to\infty$ is such that 
\begin{equation} 0<\lim_{n\rightarrow\infty}n^{1/(2k+1)}\cdot \epsilon_n < \infty
.\end{equation}

In other words, we look at the manifold as a local graph of a function 
\begin{equation}
f_{\ell}:\mathbb{R}^d\simeq H_\ell \to \mathbb{R}^{D-d} \simeq H_\ell ^\perp 
.\end{equation}

Following this, we define 
\begin{equation} f_{\ell+1/2}:(q_\ell, H_{\ell+1}) \to H_{\ell+1} ^\perp \simeq \mathbb{R}^{D-d}
\end{equation} 
using the graph $\Gamma_{f_{\ell+1/2}, q_\ell, H_{\ell+1}}$, defined similarly to \eqref{eq:Graph_fl}.

Finally, we update $q_\ell$ by taking 
\begin{equation} q_{\ell+1} = q_\ell + (0, \pi^*_{q_{\ell }, H_{\ell+1}}(0))_{H_{\ell + 1}} ,
\end{equation}
and then, we have 
\begin{equation} f_{\ell+1}:(q_{\ell+1}, H_{\ell+1}) \to H_{\ell+1} ^\perp \simeq \mathbb{R}^{D-d}    
\end{equation}

Therefore, the difference between $f_{\ell+1}$ and $f_{\ell +1/2}$ is merely in the location of the origin ($q_{\ell+1}$ instead of $q_\ell$). That is, $q_{\ell+1} - q_\ell \perp H_{\ell+1}$ and
\begin{equation} f_\ell = f_{\ell + 1/2} - \pi^*_{q_\ell, H_{\ell+1}}(0)
.\end{equation}

Finally, after performing $\kappa$ iterations we get the estimate for $ p\in \mathcal{M}$ and $ T_{ p}\mathcal{M} $ by 
\begin{equation}
    \hat p_n \stackrel{\bigtriangleup}{=} q_\kappa ,\quad \widehat{T_{\hat p_n}\mathcal{M}} \stackrel{\bigtriangleup}{=} H_\kappa
.\end{equation}

\Repeat
    \State $q_{prev} = q$
    \State $\tilde{R} = (R - repmat(q,1,N))\cdot \Theta$ \Comment{where $\Theta$ is an indicator for points in $U_{\textrm{ROI}}$}
    \State $X_{N\times d} = \tilde{R}^T U$ \Comment{find the representation of $r_i$ in $Col(U)$}
    \State define $\tilde{X}_{N\times (d+1)} = \left[(1,...,1)^T, X\right]$
    \State solve $\tilde{X}^T\tilde{X}\alpha = \tilde{X}^T \tilde{R}^T$ for $\alpha \in M_{(d+1)\times n}$ \Comment{solving the LS minimization of $\tilde{X}\alpha \approx \tilde{R}^T$}
    \State $\tilde{q} = q + \alpha(1,:)^T$
    \State $Q, \hat{R} = qr(\alpha(2:end, :)^T)$ \Comment{where $qr$ denotes the QR decomposition}
    \State $U \leftarrow Q$
    \State $q = \tilde{q} + U U^T (r-\tilde{q})$

Then, when we focus on $j\in\mathcal{K}'$ we show that for $a_1 = \frac{1}{4}$ and $a_2 = \frac{1}{8}$ and $x_0\in T_{p_r}\mathcal{M}$ such that $\norm{{p_r} - x_0} = a_1\sqrt{\sigma\tau}$ and $B_{T_{p_r}\mathcal{M}}(x_0, a_2 \sqrt{\sigma\tau} + \sigma)\subset B_D({p_r}, \sqrt{\sigma \tau} - \sigma) \subset U_\textrm{ROI}$, and 
    \begin{equation} \lrangle{r_i - {p_r}, \tilde y_j}^2 \geq \frac{1}{64}\sigma \tau sin\alpha - \frac{1}{2}\sigma^{3/2}\tau^{1/2}
    .\end{equation}

From Assumption \ref{assume:noise} in Section \ref{sec:SamplingAssumptions} we know that $ \sqrt{\frac{\sigma}{\tau}} < \frac{1}{2} $. 
    In addition, setting $ \rho = a_2 \sqrt{\sigma \tau} $ we know that $ B_{T_{p_r}\mathcal{M}}(x_0, \rho+\sigma)\subset B_{T_{p_r}\mathcal{M}}({p_r}, \sqrt{\sigma \tau} - \sigma) $, so we can use Lemma \ref{lem:num_of_samples_in_a_ball_clean}.
    Explicitly, let $\mathrm{V}_d = \frac{\pi^{d/2}}{\Gamma(d/2+1)}$ be the volume of a $ d $-dimensional unit ball, and denote 
     \begin{align*}
    \mu_{\min} &= \mathrm{V}_{D-d}\sigma^{D-d} \min_{\substack{p\in \mathcal{M}\\ x\in B_{T_p\mathcal{M}}(0,\sqrt{\sigma\tau}- \sigma)}}  \sqrt{det(G_p(x))}\\
    \mu_{\max} &= \mathrm{V}_{D-d}\sigma^{D-d}\max_{\substack{p\in \mathcal{M} \\ x \in B_{T_p\mathcal{M}}(0,\sqrt{\sigma\tau}- \sigma)}}  \sqrt{det(G_p(x))}
    ,
    \end{align*}
    where $ \mathrm{Vol}(B_{{T_p\mathcal{M}}^\perp}(\sigma)) $ is the volume of a $ D-d $ dimensional ball with radius $ \sigma $ and $ G_p $ is the matrix representing the Riemannian metric at $ p $ in the chart $ \varphi_p $ of \eqref{eq:phi_def_clean}.
    Then, from Lemma \ref{lem:num_of_samples_in_a_ball_clean}, we get that for any $ \varepsilon, \delta $ there is $ N $ such that for all $ n > N $
    \begin{align*}
    &\#\{r_i|P_{T_p\mathcal{M}}(r_i) \in B_{T_p\mathcal{M}}(x_0,\rho) \}
    \leq
    n(2\cdot \mu_{min}\cdot \mathrm{V}_d \cdot\rho^d+\varepsilon) \\
    &\#\{r_i|P_{T_p\mathcal{M}}(r_i) \in B_{T_p\mathcal{M}}(x_0,\rho+\sigma) \}
    \geq
    n \left(\frac{\mu_{max}}{2}\cdot \mathrm{V}_{d}\cdot \rho^d - \varepsilon\right)
    \end{align*}
    with probability of at least $1-\delta$.
    By setting $ \varepsilon $ appropriately we get 
    \begin{align*}
    &\#\{r_i|P_{T_p\mathcal{M}}(r_i) \in B_{T_p\mathcal{M}}(x_0,\rho) \}
    \leq
    3 n \cdot\mu_{min}\cdot \mathrm{V}_d \cdot\rho^d \\
    &\#\{r_i|P_{T_p\mathcal{M}}(r_i) \in B_{T_p\mathcal{M}}(x_0,\rho+\sigma) \}
    \geq
    \frac{n}{3}  \cdot\mu_{max}\cdot \mathrm{V}_{d} \cdot \rho^d 
    .\end{align*}

Combining \eqref{eq:RpRpp_clean} with \eqref{eq:R1pp_bound_clean} and \eqref{eq:R1p_bound_clean}, we get that for $\alpha = \sqrt{C_M/M}$, where $M = \frac{\tau}{\sigma}$, and $C_M$ is a constant the following holds:
    For any $ \delta > 0$ there is $ N $ such that for all $ n > N $ 
    \begin{equation}
        R_1(r;p,H) \geq 109 \sigma^2
    ,\end{equation}
    with probability of at least $1-\delta$.

From Claim \ref{thm:claim_J1H_clean} above, since $J_1(r;{p_r},T_{p_r}\mathcal{M}) \geq 0$ we achieve that with probability of at least $1-\delta$ there is $N_\delta$ large enough such that for all $ n > N_\delta $
    \[
       J_1(r; p, H) \geq 109 \sigma^2  
    ,\]
    as required.

\end{enumerate}



\begin{figure}
	\centering
	\includegraphics[width=0.3\textwidth]{Lk.pdf}
	\caption{ Illustration of $\mathcal{L}_{\tilde j}$ and the sections $L_1,L_2,L_3,L_4$. $U_{bad}$ is marked in light green and $U_{good}$ is marked in light pink. The angles $\angle (\tilde y_{\tilde j}, y_{\tilde j}), \angle (w_{\tilde j},u_{\tilde j})$ which equal to $\beta_{\tilde j}$ are marked in black. The bisectors of these angles are marked in dotted red lines.} \end{figure}

Below in the proof of Claim \ref{thm:claim_ri_tyk_bound_clean} we show that \eqref{eq:ri_tyk_bound_clean} holds (the proof below is independent of the current one, but utilizes the notion of $U_{good}$ defined above).
Explicitly, for $ r_i \in U_{good} $
\begin{equation*}
\lrangle{r_i - p, \tilde y_j}^2 \geq \frac{1}{64}\sigma \tau \sin\alpha_0 - \frac{1}{2}\sigma^{3/2}\tau^{1/2}
.\end{equation*}
Combining this with Lemma \ref{lem:num_of_samples_in_a_ball_clean} we get that for any $\delta$ there is $N$ large enough such that for all $n>N$  with probability of at least $1-\delta$
\begin{align*}
R_1'(r; p, H) 
&\geq 
\frac{\frac{n}{3}\cdot \mu_{max}\cdot \mathrm{V}_d \cdot(a_2\sqrt{\sigma\tau})^d}{3n\cdot\mu_{min}\cdot V\cdot ( \sqrt{\sigma\tau}+\sigma)^d}\left(\frac{1}{64}\sigma\tau sin\alpha_0 -  \frac{1}{2}\sigma^{3/2}\tau^{1/2} \right)
-9\sigma^2 \\
&=
\frac{ a_2^d\cdot\mu_{max}}{9\cdot\mu_{min}}\left(\frac{ 1}{1+\sqrt{\sigma/\tau}}\right)^d\left(\frac{1}{64}\sigma\tau sin\alpha_0 - \frac{1}{2}\sigma^{3/2}\tau^{1/2} \right)
-9 \sigma^2
.\end{align*}

Since 
$$ 
B_D(p, \sqrt{\sigma\tau}-\sigma ) \subset B_D(r, \sqrt{\sigma\tau}) = U_\textrm{ROI}
$$
(see the blue disc on $T_p\mathcal{M}$ in Figure \ref{fig:ManifoldGoodDisc_clean}), we look for a point $x_0\in T_p\mathcal{M}\cap \mathcal{L}_{\tilde j}$ and a radius $\rho >0$ such that $\Gamma_{\phi_p, B_{T_p\mathcal{M}}(x_0, \rho)}^\sigma\subset B_D(p, \sqrt{\sigma\tau} - \sigma)$, where
\begin{equation}
    \Gamma_{\phi_p, B_{T_p\mathcal{M}}(x_0, \rho)}^\sigma \stackrel{\bigtriangleup}{=} \{x ~|~ dist(x, \Gamma_{\phi_p, B_{T_p\mathcal{M}}(x_0, \rho)}) < \sigma\}
,\end{equation}
where we remind that
\[
\Gamma_{\phi_p, B_{T_p\mathcal{M}}(x_0, \rho)} = \{p + (x, \phi_p(x))_{T_p\mathcal{M}} ~|~ x\in B_{T_p\mathcal{M}}(x_0, \rho)\}
.\]
Furthermore, we choose $x_0$ and $\rho$, such that $\lrangle{r_i - p, \tilde y_{\tilde j}}^2$ is large for any point $r_i\in\Gamma_{\phi_p, B_{T_p\mathcal{M}}(x_0, \rho)}^\sigma$ (see Figure \ref{fig:ManifoldGoodDisc_clean} for an illustration).

In order to make sure that $\Gamma^\sigma_{\phi_p, B_{T_p\mathcal{M}}(x_0, \rho)}\subset U_{\textrm{ROI}}$ we restrict the choice of $a_1, a_2$ such that
\begin{equation} \forall x\in B_{T_p\mathcal{M}}(x_0, a_2\sqrt{\sigma\tau}): \norm{p+(x,\phi_p(x))_{T_p\mathcal{M}} ~-~ p}
    + \sigma < \sqrt{\sigma\tau} - \sigma
,\end{equation}
We wish to reiterate that $U_\textrm{ROI} = \{r_i ~|~ \norm{r - r_i}\leq \sqrt{\sigma \tau}\}$ and so $U_\textrm{ROI}\subset B_D(r, \sqrt{\sigma\tau})$.
Furthermore, since $\norm{r - p}\leq \sigma$, we have $B_D(p, \sqrt{\sigma\tau} - \sigma)\subset  B_D(r, \sqrt{\sigma\tau})$.
Accordingly, all points $p+(x, \phi_p(x))_{T_p\mathcal{M}}$ for  $x\in B_{T_p\mathcal{M}}(x_0, a_2 \sqrt{\sigma\tau})$ are within our region of interest even when moved $\sigma$ away from the manifold in some direction into $\mathcal{M}_\sigma$ (in Fig. \ref{fig:ManifoldGoodDisc_clean}  $B_{T_p\mathcal{M}}(x_0, a_2\sqrt{\sigma\tau})$ is the orange disc and the projections of $p+(x, \phi_p(x))_{T_p\mathcal{M}} + \varepsilon(x)$ onto $T_p\mathcal{M}$ are limited by the green disc containing the orange disc).
Using the calculations in Appendix \ref{subsec:simplification_app} we can use a simpler demand using $a_1$ and $a_2$, which ensures that the inequality \eqref{eq:a1a2_restriction_clean} is satisfied. The simplified requirement is
\begin{equation} (a_1+a_2)<\frac{1}{\sqrt{2}} -\frac{\sqrt{2\sigma}}{\sqrt{\tau}}
.\end{equation}

Similar to \eqref{eq:FunctionGraph_init} and using the result of Lemma \ref{lem:M_is_locally_a_fuinction_clean}, we begin by looking at the manifold patch $\mathcal{M} \cap \textrm{Cyl}_{H_0}(p,c_{\pi/4}\tau,\tau/2)$ as the graph of a function $f_{-1/2}:(q_{-1},H_0) \simeq\mathbb{R}^d\to\mathbb{R}^{D-d}$; i.e., 
\begin{equation}
 \Gamma_{f_{-1/2}, q_{-1},H_0} \stackrel{\bigtriangleup}{=} \{q_{-1} + (x, f_{-1}(x))_{H_0} ~|~ x\in B_{H_0}(0, c_{\pi/4}\tau)\}  
,\end{equation}
where $\textrm{Cyl}_{H_0}(p,c_{\pi/4}\tau, \tau/2)$ is the $D$-dimensional cylinder with the base $B_H(p, c_{\pi/4}\tau)\subset H_0$ and height $\tau/2$ in any direction on $H_0^\perp$.

Subsequently, we look at the function $f_0:(q_0,H_0) \simeq \mathbb{R}^d\to\mathbb{R}^{D-d}$ taking us from the shifted coordinate system $(q_0, H_0)$ to $\mathcal{M}$; i.e., $\mathcal{M}$ is now locally expressed by the graph 
\begin{equation}
 \Gamma_{f_0, q_0, H_0} \stackrel{\bigtriangleup}{=} \{q_{0} + (x, f_0(x))_{H_0} ~|~ x\in B_{H_0}(0,c_{\pi/4}\tau)\}
.\end{equation}

In our case, we measure the distance between two subspaces by taking the maximal principal angle (maximal angle) , and denote it as
\begin{equation} \angle_{\max}(\mathcal{U},\mathcal{W}) \stackrel{\bigtriangleup}{=} \max_{1\leq i\leq d}\beta_i
.\end{equation}

