Thus, our goal is to bound, for any $\vec{z}\in \mathbb{S}_{\wtilde{D} - 1}$  the expression $\mathbb{E}((\eta_\ell\cdot \vec{z})^2)$. From the definition of $g$ and $\Omega$ in \eqref{eq:g_def} and \eqref{eq:Omega_def}, we have that
\begin{align} \mathbb{E}((\eta_\ell\cdot \vec{z})^2) &= \frac{\int\limits_{y\in\Omega(x)} (y \cdot \vec{z})^2 dy}{\int\limits_{y\in\Omega(x)} dy} = 
\frac{\int\limits_{\mathbb{S}_{\wtilde D - 1}}\int\limits_0^{g(x,\theta)} (\theta \cdot \vec{z})^2 r^2 r^{\wtilde D-1} drd\theta}{\int\limits_{\mathbb{S}_{\wtilde D - 1}}\int\limits_0^{g(x,\theta)} r^{\wtilde D-1} drd\theta} \notag\\
& = \frac{\wtilde D\int\limits_{\mathbb{S}_{\wtilde D - 1}}(\theta \cdot \vec{z})^2 g(x,\theta)^{\wtilde D+2} d\theta}{(\wtilde D+2)\int\limits_{\mathbb{S}_{\wtilde D - 1}}g(x,\theta)^{\wtilde D} drd\theta}     
,\end{align}
where $dr$ is the measure over the radial component, $r^{\wtilde D-1}$ is the Jacobian introduced by the change of variables and $d\theta$ is the measure over the $(\wtilde D-1)$-dimensional sphere.

Following the rationale of the proof of Lemma \ref{lem:bound_Df-Dfwtilde}, we split $\mathbb{S}_{\wtilde D-1}$ into $\Omega_1$ and $\Omega_2$ of \eqref{eq:Omegas_def}.
That is,
\begin{equation*}
    \begin{aligned}
    \Omega_1 &= \{\theta~|~0\leq \vec{z}^T\theta \leq \xi\}\\
    \Omega_2 &= \{\theta~|~\vec{z}^T\theta > \xi\}
    \end{aligned}
,\end{equation*}
for some $\xi$ to be chosen later.
Thus, denoting $z = \theta^T \vec{z}$ we rewrite \eqref{eq:E(Z_z)} as` 
\begin{align*}
\mathbb{E}((\eta_\ell\cdot \vec{z})^2)   &=\frac{\wtilde D\left(\int\limits_{\Omega_1}z^2 g(x,\theta)^{\wtilde D+2} d\theta + \int\limits_{\Omega_2}z^2 g(x,\theta)^{\wtilde D+2} d\theta\right)}{(\wtilde D+2)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta} 
\\
&\leq  \frac{\wtilde D\left(\xi^2 \int\limits_{\Omega_1} g(x,\theta)^{\wtilde D+2} d\theta + \int\limits_{\Omega_2} g(x,\theta)^{\wtilde D+2} d\theta\right)}{(\wtilde D+2)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta} 
\end{align*}

Since the conditions of Lemma \ref{lem:g_bond_weak} are met, we have $\sigma \leq g(0,\theta)\leq \sigma + 4\sigma \alpha_\ell ^2$, and thus
\begin{align*}
\mathbb{E}((\eta_\ell\cdot \vec{z})^2)
&\leq  \frac{\wtilde D\left(\xi^2 \int\limits_{\Omega_1} g(x,\theta)^{\wtilde D+2} d\theta + \int\limits_{\Omega_2} g(x,\theta)^{\wtilde D+2} d\theta\right)}{(\wtilde D+2)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta}
\\
&\leq  \frac{\wtilde D\sigma^2(1+4\alpha_\ell ^2)^2\left(\xi^2  \int\limits_{\Omega_1} g(x,\theta)^{\wtilde D} d\theta + \int\limits_{\Omega_2} g(x,\theta)^{\wtilde D} d\theta\right)}{(\wtilde D+2)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta}
\\
&\leq  \frac{\wtilde D\sigma^2(1+4\alpha_\ell ^2)^2}{\wtilde D+2}\left(\xi^2  +\frac{ \int\limits_{\Omega_2} g(x,\theta)^{\wtilde D} d\theta}{\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta} \right)
\\
&\leq  \frac{\wtilde D\sigma^2(1+4\alpha_\ell ^2)^2}{\wtilde D+2}\left(\xi^2  +\frac{\sigma^{\wtilde D}(1+4\alpha_\ell ^2)^{\wtilde D} \int\limits_{\Omega_2} d\theta}{\sigma^{\wtilde D}\int\limits_{\mathbb{S}_{\wtilde D-1}} d\theta} \right)
\\
&\leq  \frac{\wtilde D\sigma^2(1+4\alpha_\ell ^2)^2}{\wtilde D+2}\left(\xi^2 +\frac{(1+4\alpha_\ell ^2)^{\wtilde D}}{\xi\sqrt{\wtilde D-1}} e^{-(\wtilde D-1)\xi^2/2}\right)
,\end{align*}
where the last inequality comes from Eq. \eqref{eq:Omega3_to_ball_ratio}.

Since $\alpha_\ell <1/D^{1/4}$ we have that $(1+4\alpha_\ell ^2)^{\wtilde D}$ is bounded by some constant $c$. Choosing $\xi = 2\sqrt{\frac{\log(\wtilde D-1)}{\wtilde D-1}}$ we have 
\begin{align*}
\mathbb{E}((\eta_\ell\cdot \vec{z})^2)
&\leq  \frac{\wtilde D\sigma^2(1+4\alpha_\ell ^2)^2 }{\wtilde D+2}\left(4\frac{\log(\wtilde D-1)}{\wtilde D-1} +\frac{c}{2\sqrt{\log(\wtilde D-1)}} (\wtilde D-1)^{-2}\right)
\\
&\leq  c_1\sigma^2\frac{\log(\wtilde D-1)}{\wtilde D-1}\leq  \sqrt{\frac{c\sigma}{\wtilde D}}
\end{align*}
for some constants $c,c_1$. Combining with Eq. 
\eqref{eq:cov_norm2}, we conclude the proof.

In this proof we will assume that $\alpha_\ell  \geq\frac{1}{D}$. The case when $\alpha_\ell <\frac{1}{D}$ will be treated at the end of this proof.
Using the triangle inequality, we have 
    \begin{equation} \|f_\ell(0)\| \leq \| \wtilde{f}_\ell(0) \| + \| \wtilde{f}_\ell(0)  - f_\ell(0)\|.
    \end{equation}
    and from Lemma \ref{lem:dist_q_l_and f_tilde0} we have that 
    \begin{equation} \| \wtilde{f}_\ell(0)\| \leq \frac{C_2\ln\left(\frac{1}{\delta}\right)}{n^{r_0}}
    \end{equation}
    with probability of at least $1-\delta$.

Similar to \eqref{eq:f_tilde-f_integrals} of the proof of Lemma \ref{lem:bound_Df-Dfwtilde} we can write 
\begin{equation*}
\wtilde{f}_\ell(x) - f_\ell(x)=
\frac{\wtilde D\int\limits_{\mathbb{S}_{\wtilde D-1}}\theta g(x,\theta)^{\wtilde D+1} d\theta}{(\wtilde D+1)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} drd\theta}    ,\end{equation*}
where $\wtilde D = D - d$, and $\mathbb{S}_{\wtilde D - 1}$ is the $({\wtilde D - 2})$-dimensional unit sphere in $\mathbb{R}^{\wtilde D - 1}$.
Following the rationale of the proof of Lemma \ref{lem:bound_Df-Dfwtilde}, we split $\mathbb{S}_{\wtilde D-1}$ into $\Omega_1$ and $\Omega_2$ of \eqref{eq:Omegas_def}.
That is,
\begin{equation*}
    \begin{aligned}
    \Omega_1 &= \{\theta~|~0\leq \vec{z}^T\theta \leq \xi\}\\
    \Omega_2 &= \{\theta~|~\vec{z}^T\theta > \xi\}
    \end{aligned}
,\end{equation*}
for some $\xi$ to be chosen later.
Thus, we have  
\begin{align*}
z^T\cdot (\wtilde{f}_\ell(x) - f_\ell(x))&=
\frac{\wtilde D\int\limits_{\mathbb{S}_{\wtilde D-1}}z g(x,\theta)^{\wtilde D+1} d\theta}{(\wtilde D+1)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta} 
\\
&=\frac{\wtilde D\left(\int\limits_{\Omega_1}z g(x,\theta)^{\wtilde D+1} d\theta + \int\limits_{\Omega_2}z g(x,\theta)^{\wtilde D+1} d\theta\right)}{(\wtilde D+1)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta} 
\\
&\leq  \frac{\wtilde D\left(\xi \int\limits_{\Omega_1} g(x,\theta)^{\wtilde D+1} d\theta + \int\limits_{\Omega_2} g(x,\theta)^{\wtilde D+1} d\theta\right)}{(\wtilde D+1)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta} 
\end{align*}

Since the conditions of Lemma \ref{lem:g_bond_weak} are met, we have $\sigma \leq g(0,\theta)\leq \sigma + 4\sigma \alpha_\ell ^2$, and thus
\begin{align*}
z^T\cdot (\wtilde{f}_\ell(x) - f_\ell(x))
&\leq  \frac{\wtilde D\left(\xi \int\limits_{\Omega_1} g(x,\theta)^{\wtilde D+1} d\theta + \int\limits_{\Omega_2} g(x,\theta)^{\wtilde D+1} d\theta\right)}{(\wtilde D+1)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta}
\\
&\leq  \frac{\wtilde D\sigma(1+4\alpha_\ell ^2)\left(\xi  \int\limits_{\Omega_1} g(x,\theta)^{\wtilde D} d\theta + \int\limits_{\Omega_2} g(x,\theta)^{\wtilde D} d\theta\right)}{(\wtilde D+1)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta}
\\
&\leq  \frac{\wtilde D\sigma(1+4\alpha_\ell ^2)}{\wtilde D+1}\left(\xi  +\frac{ \int\limits_{\Omega_2} g(x,\theta)^{\wtilde D} d\theta}{\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta} \right)
\\
&\leq  \frac{\wtilde D\sigma(1+4\alpha_\ell ^2)}{\wtilde D+1}\left(\xi  +\frac{\sigma^{\wtilde D}(1+4\alpha_\ell ^2)^{\wtilde D} \int\limits_{\Omega_2} d\theta}{\sigma^{\wtilde D}\int\limits_{\mathbb{S}_{\wtilde D-1}} d\theta} \right)
\\
&\leq  \frac{\wtilde D\sigma(1+4\alpha_\ell ^2)}{\wtilde D+1}\left(\xi  +\frac{(1+4\alpha_\ell ^2)^{\wtilde D}}{\xi\sqrt{\wtilde D-1}} e^{-(\wtilde D-1)\xi^2/2}\right)
\end{align*}

Since $\alpha_\ell <1/D^{1/4}$ we have that $(1+4\alpha_\ell ^2)^{\wtilde D}$ is bounded by some constant $c$. Choosing $\xi = 2\sqrt{\frac{\log(\wtilde D-1)}{\wtilde D-1}}$ we have 
\begin{align*}
z^T\cdot (\wtilde{f}_\ell(x) - f_\ell(x))
&\leq  \frac{\wtilde D\sigma(1+\alpha_\ell )}{\wtilde D+1}\left(2\sqrt{\frac{\log(\wtilde D-1)}{\wtilde D-1}} +\frac{c}{2\sqrt{\log(\wtilde D-1)}} (\wtilde D-1)^{-2}\right)
\\
&\leq  c_1\sigma\sqrt{\frac{\log(\wtilde D-1)}{\wtilde D-1}} 
\end{align*}
for some constant $c_1$. Recalling that $M=\frac{\tau}{\sigma}>C_\tau \sqrt{D \log D}$ we have,
\begin{equation*}
    \|\wtilde{f}_\ell(x) - f_\ell(x)\| \leq c_1\sigma\sqrt{\frac{\log(\wtilde D-1)}{\wtilde D-1}} = \sigma C_\tau \sqrt{D\log D} \frac{c_1}{C_\tau D}\leq \tau \frac{c_1}{C_\tau D}.
\end{equation*}
and thus, for $\alpha_\ell \geq 1/D$, and for large enough $\mathcal{C}_\tau$ we have that 
\begin{equation*}
    \|\wtilde{f}_\ell(x) - f_\ell(x)\|\leq \frac{\tau \alpha_\ell }{2\cdot 48}.
\end{equation*}

Using the triangle inequality, we have 
\begin{equation} \|f_\ell(0)\| \leq \| \wtilde{f}_\ell(0) \| + \| \wtilde{f}_\ell(0)  - f_\ell(0)\|.
\end{equation}
and Lemma \ref{lem:dist_q_l_and f_tilde0} we have that 
\begin{equation} \| \wtilde{f}_\ell(0)\| \leq \frac{C_2\ln\left(\frac{1}{\delta}\right)}{n^{r_0}}
\end{equation}
with probability of at least $1-\delta$.

Now we focus on bounding $\| \wtilde{f}_\ell(0)  - f_\ell(0)\|$

  From \eqref{eq:f_tilde-f_integrals} we have that 
\begin{equation*}
\wtilde{f}_\ell(x) - f_\ell(x)=
\frac{\wtilde D\int\limits_{\mathbb{S}_{\wtilde D-1}}\theta g(x,\theta)^{\wtilde D+1} d\theta}{(\wtilde D+1)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} drd\theta}     
=
\frac{\wtilde D\int\limits_{\mathbb{S}_{\wtilde D-1}}\theta (g(x,\theta)^{\wtilde D+1} - \sigma^{\wtilde D+1}) d\theta}{(\wtilde D+1)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} drd\theta}     
\end{equation*}
or, looking at some direction $\vec{z}$ we have 
\begin{align*}
z^T\cdot (\wtilde{f}_\ell(x) - f_\ell(x))&=
\frac{\wtilde D\int\limits_{\mathbb{S}_{\wtilde D-1}}z (g(x,\theta)^{\wtilde D+1}- \sigma^{\wtilde D+1}) d\theta}{(\wtilde D+1)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta} 
\\
&\leq
\frac{\wtilde D}{(\wtilde D+1)}\sigma((1+4\alpha_\ell^2)^{\wtilde D+1} - 1)
\end{align*}

Next we bound  $ \|P_{T_0g_0} (o_1 + (0, g_{1}(0))_{G_1} - \tilde o_1) \| $.
Since $\wtilde{g}_1(0) = 0$, from Lemma \ref{lem:f_bound_circle_H_clean} and the triangle inequality for maximal angles between flats
we have that 
\[
\|\wtilde{g}_1(x_o)\| \leq \tau\cos(\alpha + \beta)-\sqrt{\tau^2-(\norm{x_o} + \tau\sin(\alpha+\beta))^2}
\]
Substituting $\|x_o\|$ in the right hand side we set 
\begin{align}
\|\wtilde{g}_1(x_o)\| &\leq \tau\cos(\alpha + \beta)-\sqrt{\tau^2-(\frac{3\tau}{4 \cdot 16} \sin \beta + \tau\sin(\alpha+\beta))^2} \notag\\
&= \tau \left( \cos(\alpha + \beta)-\sqrt{1-(\frac{3}{4 \cdot 16} \sin \beta + \sin(\alpha+\beta))^2} \right)    
\end{align}
Since  
\begin{multline}
 \|P_{T_0g_0} (o_1 + (0, g_{1}(0))_{G_1} - \tilde o_1) \| \leq \norm{o_1 + (0, g_{1}(0))_{G_1} - \tilde o_1)}   = \sqrt{\|\wtilde{g}_1(x_o)\|^2 + \|x_o\|^2} 
\\
= \tau \sqrt{\left(\frac{3}{4 \cdot 16}\right)^2 \sin^2 \beta + \left( \cos(\alpha + \beta)-\sqrt{1-(\frac{3}{4 \cdot 16} \sin \beta + \sin(\alpha+\beta))^2} \right)^2 }
\end{multline}
which, for small enough $\beta$ and fixed $\alpha$ is smaller than $0.5 \tau$.
